mapper.select:
        SELECT mn.*,
        c1.d_Name as applicationCompanyName
        FROM project_application mn
        left join SYS_Department c1 on c1.d_Id=mn.application_company_id
        
            
                and mn.project_name like concat('%',#{projectName},'%')
            
            
                and mn.application_company_id=#{applicationCompanyId}
            
            
                and mn.plan_year=#{planYear}
            
            
                and mn.project_type=#{projectType}
            
            
                and mn.project_manager like concat('%',#{projectManager},'%')
            
            
                and mn.application_num like concat('%',#{applicationNum},'%')
            
            
                and mn.task_status=#{taskStatus}
            
            
                and mn.approve_status=#{approveStatus}
            
            
                and c1.D_Name like concat('%',#{applicationCompanyName},'%')
            
            
                and mn.task_status in
                
                    #{item}
                
            
            
                
                    and (
                    mn.create_id=#{createId}
                    
                    or
                        
                            mn.relevant_depart_id like concat('%',#{createDepartId},'%')
                        
                    
                    )
                
            
        
        
            
                order by CASE WHEN mn.${sortFiled} IS NULL THEN 0 ELSE mn.${sortFiled} END ${sortType}
            
            
                
                order by CASE WHEN mn.pre_approve_score IS NULL THEN 0 ELSE mn.pre_approve_score END desc
                
                
                    order by CASE WHEN mn.pre_approve_score IS NULL THEN 0 ELSE mn.pre_approve_score END desc
                
                
                    order by CASE WHEN mn.final_approve_score IS NULL THEN 0 ELSE mn.final_approve_score END desc
                
                
                    order by CASE WHEN mn.final_approve_score IS NULL THEN 0 ELSE mn.final_approve_score END desc
